import{_ as l,C as r,o as i,c as s,a5 as a,E as n}from"./chunks/framework.BF53ZjCA.js";const b=JSON.parse('{"title":"圆明亮式切工","description":"","frontmatter":{"title":"圆明亮式切工","cutting":"brilliant-cut"},"headers":[],"relativePath":"zh/cutting/brilliant-cut.md","filePath":"zh/cutting/brilliant-cut.md","lastUpdated":1790876393000}'),o={name:"zh/cutting/brilliant-cut.md"};function d(c,e,h,u,_,m){const t=r("FacetDiagram");return i(),s("div",null,[e[0]||(e[0]=a('<h1 id="圆明亮式切工" tabindex="-1">圆明亮式切工 <a class="header-anchor" href="#圆明亮式切工" aria-label="Permalink to &quot;圆明亮式切工&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>圆明亮式是经典的刻面风格之一，最常见于钻石。1919 年 Marcel Tolkowsky 对相关比例体系的研究使其成为讨论台面、冠部、腰棱和亭部关系的经典参考。 对于适合该比例体系的透明材料，合理的部位关系有助于提升亮度、闪烁与火彩表现。</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-brilliant-cut-zh"><p class="gem-identification-boundary__eyebrow">CUTTING BOUNDARY</p><h2 id="identification-boundary-brilliant-cut-zh">边界与安全</h2><p>本页的比例与面数用于建立术语和分析起点，不是对所有材料的固定加工处方； 实际方案还需结合折射率、原石形状、包裹体、耐久性、设备和切割师复核。 </p></aside><h2 id="结构示意" tabindex="-1">结构示意 <a class="header-anchor" href="#结构示意" aria-label="Permalink to &quot;结构示意&quot;">​</a></h2>',5)),n(t,{locale:"zh"}),e[1]||(e[1]=a('<h2 id="案例流程" tabindex="-1">案例流程 <a class="header-anchor" href="#案例流程" aria-label="Permalink to &quot;案例流程&quot;">​</a></h2><blockquote><p>教学案例（演示）：以下用来说明比例如何进入分析，不代表某颗宝石的最终方案。</p></blockquote><h3 id="_1-先确认材料边界" tabindex="-1">1. 先确认材料边界 <a class="header-anchor" href="#_1-先确认材料边界" aria-label="Permalink to &quot;1. 先确认材料边界&quot;">​</a></h3><p>记录材料的折射率、透明度、原石形状和耐久性风险；如果材料不适合直接套用圆明亮式， 先退回到轮廓与耐久性的比较，不急于套用角度数字。</p><h3 id="_2-建立比例起点" tabindex="-1">2. 建立比例起点 <a class="header-anchor" href="#_2-建立比例起点" aria-label="Permalink to &quot;2. 建立比例起点&quot;">​</a></h3><p>用台面、冠部、腰棱和亭部关系建立第一版模型，再检查预期的亮度、闪烁和火彩表现。 57/58 面用于统一术语，不能单独证明成品质量。</p><h3 id="_3-做可观察验证" tabindex="-1">3. 做可观察验证 <a class="header-anchor" href="#_3-做可观察验证" aria-label="Permalink to &quot;3. 做可观察验证&quot;">​</a></h3><p>在统一光源、观察方向和背景下记录是否出现漏光、暗区、偏心或腰棱薄弱；把“观察到的现象” 与“可能原因”分开记录，避免把一次观察直接写成评级。</p><h3 id="_4-停止条件" tabindex="-1">4. 停止条件 <a class="header-anchor" href="#_4-停止条件" aria-label="Permalink to &quot;4. 停止条件&quot;">​</a></h3><p>当比例、材料折射率、包裹体或耐久性之间出现冲突时，停止给出单一最佳答案，转为记录候选 方案并交由切割师结合设备和原石复核。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>常见标准为不计底尖 57 面：台面 1 + 冠部其余 32 + 亭部 24；计入底尖后为 58 面。</li><li>台面直径比约 53–58%；冠角 34–35°；亭角 40.75–41.2°。</li><li>腰棱厚度适中——过薄易崩，过厚浪费重量。</li><li>全反射率 (total internal reflection) 依赖比例精确；比例失调导致&quot;漏光窗&quot;。</li><li>这些比例是分析起点而非所有宝石的固定处方；折射率、色散、形状和耐久性都会改变最佳方案。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>切工</th><th>备注</th></tr></thead><tbody><tr><td>钻石</td><td>圆明亮式，57 面</td><td>示例条目</td></tr><tr><td>锆石</td><td>圆明亮式</td><td>高色散材料示例</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/gia-news-research-value-factors-gem-cutting-styles-definitions" target="_blank" rel="noreferrer">GIA：宝石切工风格定义</a><span>轮廓、刻面排列、阶梯式、蛋面与雕刻等切工风格的定义</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA：有色宝石价值要素与切工质量</a><span>比例、对称性、抛光、原石限制与视觉表现之间的切工取舍</span><small>打开来源 ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-cut/" target="_blank" rel="noreferrer">GIA：钻石切工与明亮度</a><span>圆明亮式的台面、冠部、腰棱、亭部，以及 57/58 面计数说明</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/emerald-quality-factor" target="_blank" rel="noreferrer">GIA：祖母绿质量要素</a><span>有色宝石切割对颜色、耐久性、包裹体与裂隙的综合考量</span><small>打开来源 ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-brilliant-cut-zh"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-brilliant-cut-zh">本页证据映射</h2><p class="gem-reference-block__intro">把本页的教学主张映射到来源，并标注它在知识库中的证据状态。</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">来源支持</strong><span>圆明亮式常见面数为不计底尖 57 面，计入底尖后为 58 面。</span><small>GIA：钻石切工与明亮度</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">来源支持</strong><span>比例应作为分析起点，而不是对所有宝石固定适用的处方。</span><small>GIA：钻石切工与明亮度；GIA：有色宝石价值要素与切工质量</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">教学归纳</strong><span>教学案例把比例起点与统一光源下的可观察复核分开记录。</span><small>GIA：钻石切工与明亮度；GIA：有色宝石价值要素与切工质量</small></li></ul></aside><p><em>详见<a href="./intro.html">切割总览</a>。</em></p>',17))])}const g=l(o,[["render",d]]);export{b as __pageData,g as default};
